title: $:/plugins/claude/bookmarks/core.js
type: application/javascript
module-type: library

Shared model for the bookmark bar: ordered entries, labels, icons and the
order bookkeeping that keeps the bar and its folders in a stable sequence.

\*/
(function(){
"use strict";

var ITEM_TAG = "$:/bookmarks/item";
var ITEM_PREFIX = "$:/bookmarks/item/";
var STEP = 10;
var MAX_DEPTH = 12;
var SCHEMES = /^(?:https?|ftp|ftps|file|mailto|tel|sms|irc|ircs|news|nntp|gopher|gemini|ipfs|ipns|magnet):/i;
var UNSAFE = /^(?:javascript|data|vbscript|blob):/i;

/* "/Dev//Tools/ " -> "Dev/Tools" so a path has exactly one spelling */
function normFolder(value){
	var parts = String(value || "").split("/"), out = [];
	for(var i = 0; i < parts.length; i++){
		var seg = parts[i].trim();
		if(seg){ out.push(seg); }
	}
	return out.join("/");
}

function itemOrder(tiddler){
	var n = parseFloat(tiddler.fields.order);
	return isFinite(n) ? n : Infinity;
}

function host(url){
	var m = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#]+)/i.exec(String(url || "").trim());
	if(!m){ return ""; }
	var h = m[1].replace(/^[^@]*@/,"").replace(/:\d+$/,"").toLowerCase();
	return /^[a-z0-9.\-¡-￿]+$/.test(h) ? h : "";
}

function bareHost(url){
	return host(url).replace(/^www\./,"");
}

/*
A URL that is safe to put in an href, or "" for one that is not. Browsers
ignore control characters inside a scheme, so "java\nscript:" runs as
"javascript:" — strip them before deciding.
*/
function safeUrl(value){
	var s = String(value || "").replace(/[\u0000-\u001f\u007f]/g,"").trim();
	return UNSAFE.test(s) ? "" : s;
}

/* Returns a usable URL, or "" when the input looks like a tiddler title */
function normaliseUrl(value){
	var s = safeUrl(value);
	if(!s){ return ""; }
	if(SCHEMES.test(s) || /^[a-z][a-z0-9+.-]*:\/\//i.test(s)){ return s; }
	if(s.indexOf("//") === 0){ return "https:" + s; }
	if(/^[^\s\/?#:]+\.[a-z]{2,}(?::\d+)?(?:[\/?#].*)?$/i.test(s)){ return "https://" + s; }
	return "";
}

function label(wiki,title){
	var tiddler = wiki.getTiddler(title);
	if(!tiddler){ return title; }
	var caption = String(tiddler.fields.caption || "").trim();
	if(caption){ return caption; }
	var target = String(tiddler.fields.target || "").trim();
	if(target){ return target; }
	return bareHost(tiddler.fields.url) || String(tiddler.fields.url || "").trim() || title;
}

/*
Entries shown inside `folder`: its own bookmarks plus one entry per
immediate subfolder. A folder sits wherever its earliest bookmark sits, so
moving bookmarks moves the folder with them.
*/
function entries(wiki,folder){
	folder = normFolder(folder);
	var prefix = folder ? folder + "/" : "";
	var items = [], seen = Object.create(null), subfolders = [];
	wiki.getTiddlersWithTag(ITEM_TAG).forEach(function(title){
		var tiddler = wiki.getTiddler(title);
		if(!tiddler){ return; }
		var own = normFolder(tiddler.fields.folder), order = itemOrder(tiddler);
		if(own === folder){
			items.push({kind:"i",key:title,order:order,label:label(wiki,title)});
			return;
		}
		if(own.substr(0,prefix.length) !== prefix){ return; }
		var seg = own.substr(prefix.length).split("/")[0];
		if(!seg){ return; }
		var path = prefix + seg;
		if(!seen[path]){
			seen[path] = {kind:"f",key:path,order:order,label:seg};
			subfolders.push(seen[path]);
		} else if(order < seen[path].order){
			seen[path].order = order;
		}
	});
	return items.concat(subfolders).sort(function(a,b){
		if(a.order !== b.order){ return a.order < b.order ? -1 : 1; }
		var x = a.label.toLowerCase(), y = b.label.toLowerCase();
		return x < y ? -1 : (x > y ? 1 : 0);
	});
}

function encode(entry){ return entry.kind + ":" + entry.key; }

/* Every bookmark title in display order, depth first */
function flatten(wiki,folder,override,acc,depth){
	if(depth > MAX_DEPTH){ return acc; }
	var list = (override && override.folder === normFolder(folder)) ? override.entries : entries(wiki,folder);
	list.forEach(function(entry){
		if(entry.kind === "i"){ acc.push(entry.key); }
		else { flatten(wiki,entry.key,override,acc,depth + 1); }
	});
	return acc;
}

function renumber(wiki,titles){
	titles.forEach(function(title,index){
		var tiddler = wiki.getTiddler(title);
		if(!tiddler){ return; }
		var order = String((index + 1) * STEP);
		if(tiddler.fields.order === order){ return; }
		wiki.addTiddler(new $tw.Tiddler(tiddler,{order:order},wiki.getModificationFields()));
	});
}

/*
Swap an entry with its neighbour inside `folder`, then renumber the whole
bar from the new arrangement. Moving a folder moves all of its bookmarks.
*/
function move(wiki,entry,folder,direction){
	folder = normFolder(folder);
	var list = entries(wiki,folder), from = -1;
	for(var i = 0; i < list.length; i++){
		if(encode(list[i]) === entry){ from = i; break; }
	}
	if(from === -1){ return false; }
	var back = (direction === "up" || direction === "left" || direction === "previous");
	var to = back ? from - 1 : from + 1;
	if(to < 0 || to >= list.length){ return false; }
	var swap = list[from];
	list[from] = list[to];
	list[to] = swap;
	renumber(wiki,flatten(wiki,"",{folder:folder,entries:list},[],0));
	return true;
}

/*
Move one entry of `folder` so that it sits immediately before the entry
`before` ("" = at the end), then renumber the bar from the new arrangement.
*/
function arrange(wiki,entry,folder,before){
	var list = entries(wiki,folder), from = -1;
	for(var i = 0; i < list.length; i++){
		if(encode(list[i]) === entry){ from = i; break; }
	}
	if(from === -1){ return false; }
	var moved = list.splice(from,1)[0], to = -1;
	if(before){
		for(var j = 0; j < list.length; j++){
			if(encode(list[j]) === before){ to = j; break; }
		}
	}
	list.splice(to === -1 ? list.length : to,0,moved);
	renumber(wiki,flatten(wiki,"",{folder:folder,entries:list},[],0));
	return true;
}

/* Re-parent a folder, then order it among its new siblings */
function placeFolder(wiki,path,folder,before){
	path = normFolder(path);
	if(!path){ return false; }
	/* A folder cannot be dropped inside itself */
	if(folder === path || folder.substr(0,path.length + 1) === path + "/"){ return false; }
	var entry = "f:" + path;
	if(folder !== parent(path)){
		var to = folder ? folder + "/" + name(path) : name(path);
		if(!rename(wiki,path,to)){ return false; }
		entry = "f:" + normFolder(to);
	}
	return arrange(wiki,entry,folder,before);
}

/*
Drop `entry` ("i:<title>" or "f:<path>") into `folder`, landing immediately
before the entry `before` ("" = at the end). Bookmarks change folder, and a
folder carries everything below it along.
*/
function place(wiki,entry,folder,before){
	folder = normFolder(folder);
	if(!entry || entry === before){ return false; }
	var key = entry.substr(2);
	if(entry.substr(0,2) === "f:"){ return placeFolder(wiki,key,folder,before); }
	if(entry.substr(0,2) !== "i:"){ return false; }
	var tiddler = wiki.getTiddler(key);
	if(!tiddler){ return false; }
	if(normFolder(tiddler.fields.folder) !== folder){
		wiki.addTiddler(new $tw.Tiddler(tiddler,{folder:folder},wiki.getModificationFields()));
	}
	return arrange(wiki,entry,folder,before);
}

function folders(wiki,folder,acc,depth){
	if(depth > MAX_DEPTH){ return acc; }
	entries(wiki,folder).forEach(function(entry){
		if(entry.kind !== "f"){ return; }
		acc.push(entry.key);
		folders(wiki,entry.key,acc,depth + 1);
	});
	return acc;
}

function nextOrder(wiki){
	var max = 0;
	wiki.getTiddlersWithTag(ITEM_TAG).forEach(function(title){
		var tiddler = wiki.getTiddler(title);
		if(!tiddler){ return; }
		var n = parseFloat(tiddler.fields.order);
		if(isFinite(n) && n > max){ max = n; }
	});
	return max + STEP;
}

function freeTitle(wiki){
	var n = 1;
	while(wiki.tiddlerExists(ITEM_PREFIX + n) || wiki.isShadowTiddler(ITEM_PREFIX + n)){ n++; }
	return ITEM_PREFIX + n;
}

function add(wiki,options){
	options = options || {};
	var target = String(options.target || "").trim();
	var input = String(options.url || "").trim();
	var url = "";
	if(!target && input){
		url = normaliseUrl(input);
		if(!url){ target = input; }
	}
	if(!url && !target){ return ""; }
	var caption = String(options.label || "").trim();
	if(!caption){
		if(target){
			var tiddler = wiki.getTiddler(target);
			caption = (tiddler && String(tiddler.fields.caption || "").trim()) || target;
		} else {
			caption = bareHost(url) || url;
		}
	}
	var title = freeTitle(wiki);
	wiki.addTiddler(new $tw.Tiddler(wiki.getCreationFields(),{
		title: title,
		tags: [ITEM_TAG],
		caption: caption,
		url: url,
		target: target,
		folder: normFolder(options.folder),
		order: String(nextOrder(wiki)),
		text: ""
	},wiki.getModificationFields()));
	return title;
}

/* Add a bookmark at a given spot on the bar, rather than at the end */
function insert(wiki,options,folder,before){
	var fields = {}, field;
	for(field in options){ fields[field] = options[field]; }
	fields.folder = folder;
	var title = add(wiki,fields);
	if(title){ arrange(wiki,"i:" + title,normFolder(folder),before); }
	return title;
}

/* Rename or re-parent a folder, carrying everything below it along */
function rename(wiki,from,to){
	from = normFolder(from);
	to = normFolder(to);
	if(!from || from === to){ return false; }
	var prefix = from + "/";
	wiki.getTiddlersWithTag(ITEM_TAG).forEach(function(title){
		var tiddler = wiki.getTiddler(title);
		if(!tiddler){ return; }
		var own = normFolder(tiddler.fields.folder), next = null;
		if(own === from){
			next = to;
		} else if(own.substr(0,prefix.length) === prefix){
			var rest = own.substr(prefix.length);
			next = to ? to + "/" + rest : rest;
		}
		if(next === null){ return; }
		wiki.addTiddler(new $tw.Tiddler(tiddler,{folder:next},wiki.getModificationFields()));
	});
	return true;
}

/* Move one bookmark into a folder, landing at the end of it */
function setFolder(wiki,title,folder){
	var tiddler = wiki.getTiddler(title);
	if(!tiddler){ return false; }
	wiki.addTiddler(new $tw.Tiddler(tiddler,{
		folder: normFolder(folder),
		order: String(nextOrder(wiki))
	},wiki.getModificationFields()));
	return true;
}

function favicon(wiki,url){
	var mode = String(wiki.getTiddlerText("$:/config/bookmarks/favicons","duckduckgo") || "").trim();
	var h = host(url);
	if(!h || mode === "off"){ return ""; }
	if(mode === "google"){ return "https://www.google.com/s2/favicons?sz=32&domain=" + encodeURIComponent(h); }
	if(mode === "direct"){ return "https://" + h + "/favicon.ico"; }
	return "https://icons.duckduckgo.com/ip3/" + encodeURIComponent(h) + ".ico";
}

function hue(value){
	var s = String(value || ""), n = 0;
	for(var i = 0; i < s.length; i++){ n = (n * 31 + s.charCodeAt(i)) % 360; }
	return n;
}

/* The favicon for a bookmark, or "" when it has none to show */
function iconSrc(wiki,title){
	var tiddler = wiki.getTiddler(title);
	return tiddler ? favicon(wiki,tiddler.fields.url) : "";
}

/*
The hashed backdrop for the 16px square. It is drawn whether or not there is
a favicon, so a favicon that 404s leaves a coloured initial rather than a
hole; the icon widget clears it once the image has actually loaded.
*/
function chipStyle(wiki,title){
	var tiddler = wiki.getTiddler(title);
	var seed = tiddler ? (host(tiddler.fields.url) || String(tiddler.fields.target || "") || label(wiki,title)) : title;
	return "background:hsl(" + hue(seed) + ",46%,42%)";
}

function initial(wiki,title){
	var text = label(wiki,title).replace(/^[\s"'(\[{<‘“]+/,"");
	return (text.charAt(0) || "•").toUpperCase();
}

function name(path){
	var parts = normFolder(path).split("/");
	return parts[parts.length - 1] || "";
}

function parent(path){
	var parts = normFolder(path).split("/");
	parts.pop();
	return parts.join("/");
}

exports.ITEM_TAG = ITEM_TAG;
exports.normFolder = normFolder;
exports.normaliseUrl = normaliseUrl;
exports.entries = entries;
exports.encode = encode;
exports.folders = folders;
exports.label = label;
exports.iconSrc = iconSrc;
exports.chipStyle = chipStyle;
exports.initial = initial;
exports.name = name;
exports.parent = parent;
exports.host = host;
exports.safeUrl = safeUrl;
exports.move = move;
exports.place = place;
exports.insert = insert;
exports.add = add;
exports.rename = rename;
exports.setFolder = setFolder;

})();
"},"$:/plugins/claude/bookmarks/filters.js":{"title":"$:/plugins/claude/bookmarks/filters.js","type":"application/javascript","module-type":"filteroperator","text":"/*\
title: $:/plugins/claude/bookmarks/filters.js
type: application/javascript
module-type: filteroperator

Filter operators the bar templates are built from.

\*/
(function(){
"use strict";
var core = require("$:/plugins/claude/bookmarks/core.js");

function mapped(fn){
	return function(source,operator,options){
		var results = [];
		source(function(tiddler,title){ results.push(fn(options.wiki,title)); });
		return results;
	};
}

/* Entries of a folder ("" = the bar itself), as "i:<title>" / "f:<path>" */
exports.bookmarkentries = function(source,operator,options){
	return core.entries(options.wiki,operator.operand || "").map(core.encode);
};

/* Every folder path below the operand, in display order */
exports.bookmarkfolders = function(source,operator,options){
	return core.folders(options.wiki,operator.operand || "",[],0);
};

exports.bookmarklabel = mapped(core.label);

/* A bookmark's URL, emptied out when it is not safe to put in an href */
exports.bookmarkurl = mapped(function(wiki,title){
	var tiddler = wiki.getTiddler(title);
	return tiddler ? core.safeUrl(tiddler.fields.url) : "";
});

exports.bookmarkname = function(source,operator,options){
	var results = [];
	source(function(tiddler,title){ results.push(core.name(title)); });
	return results;
};

exports.bookmarkparent = function(source,operator,options){
	var results = [];
	source(function(tiddler,title){ results.push(core.parent(title)); });
	return results;
};

})();
"},"$:/plugins/claude/bookmarks/widgets.js":{"title":"$:/plugins/claude/bookmarks/widgets.js","type":"application/javascript","module-type":"widget","text":"/*\
title: $:/plugins/claude/bookmarks/widgets.js
type: application/javascript
module-type: widget

Action widgets for the jobs the filter language cannot do: adding a
bookmark, reordering one, and renaming a folder.

\*/
(function(){
"use strict";
var Widget = require("$:/core/modules/widgets/widget.js").widget;
var core = require("$:/plugins/claude/bookmarks/core.js");

function action(invoke){
	var ActionWidget = function(parseTreeNode,options){ this.initialise(parseTreeNode,options); };
	ActionWidget.prototype = new Widget();
	ActionWidget.prototype.render = function(parent,nextSibling){
		this.computeAttributes();
		this.execute();
	};
	ActionWidget.prototype.execute = function(){};
	ActionWidget.prototype.refresh = function(changedTiddlers){
		var changedAttributes = this.computeAttributes();
		if(Object.keys(changedAttributes).length > 0){
			this.refreshSelf();
			return true;
		}
		return this.refreshChildren(changedTiddlers);
	};
	ActionWidget.prototype.invokeAction = function(triggeringWidget,event){
		invoke.call(this);
		return true;
	};
	return ActionWidget;
}

exports["action-bookmarkadd"] = action(function(){
	core.add(this.wiki,{
		label: this.getAttribute("label",""),
		url: this.getAttribute("url",""),
		target: this.getAttribute("target",""),
		folder: this.getAttribute("folder","")
	});
});

exports["action-bookmarkmove"] = action(function(){
	core.move(this.wiki,this.getAttribute("entry",""),this.getAttribute("folder",""),this.getAttribute("direction","up"));
});

exports["action-bookmarkrename"] = action(function(){
	core.rename(this.wiki,this.getAttribute("folder",""),this.getAttribute("to",""));
});

exports["action-bookmarkfolder"] = action(function(){
	core.setFolder(this.wiki,this.getAttribute("item",""),this.getAttribute("folder",""));
});

})();
"},"$:/plugins/claude/bookmarks/icon.js":{"title":"$:/plugins/claude/bookmarks/icon.js","type":"application/javascript","module-type":"widget","text":"/*\
title: $:/plugins/claude/bookmarks/icon.js
type: application/javascript
module-type: widget

The 16px icon chip. A favicon is drawn as a layer over a hashed colour and
the bookmark's initial, so a favicon that never arrives — a 404, a blocked
icon service, an offline wiki — leaves the initial behind instead of a hole,
and one that does arrive takes the square over.

\*/
(function(){
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;
var core = require("$:/plugins/claude/bookmarks/core.js");
var CONFIG = "$:/config/bookmarks/favicons";

var IconWidget = function(parseTreeNode,options){ this.initialise(parseTreeNode,options); };
IconWidget.prototype = new Widget();

IconWidget.prototype.render = function(parent,nextSibling){
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	var chip = this.document.createElement("span");
	chip.className = "bm-ico";
	chip.setAttribute("style",core.chipStyle(this.wiki,this.item));
	var text = this.document.createElement("span");
	text.className = "bm-ico-text";
	text.appendChild(this.document.createTextNode(core.initial(this.wiki,this.item)));
	chip.appendChild(text);
	var src = core.iconSrc(this.wiki,this.item);
	if(src){ this.addFavicon(chip,src); }
	parent.insertBefore(chip,nextSibling);
	this.domNodes.push(chip);
};

IconWidget.prototype.addFavicon = function(chip,src){
	var img = this.document.createElement("img");
	img.className = "bm-ico-img";
	img.setAttribute("alt","");
	$tw.utils.addEventListeners(img,[
		{name: "load", handlerFunction: function(){
			/* The icon is really there, so drop the colour it was standing in for */
			chip.removeAttribute("style");
			$tw.utils.addClass(chip,"bm-ico-loaded");
		}},
		{name: "error", handlerFunction: function(){
			if(img.parentNode){ img.parentNode.removeChild(img); }
		}}
	]);
	img.setAttribute("src",src);
	chip.appendChild(img);
};

IconWidget.prototype.execute = function(){
	this.item = this.getAttribute("item","");
};

IconWidget.prototype.refresh = function(changedTiddlers){
	var changedAttributes = this.computeAttributes();
	if(Object.keys(changedAttributes).length > 0 || changedTiddlers[this.item] || changedTiddlers[CONFIG]){
		this.refreshSelf();
		return true;
	}
	return false;
};

exports["bookmark-icon"] = IconWidget;

})();
"},"$:/plugins/claude/bookmarks/drag.js":{"title":"$:/plugins/claude/bookmarks/drag.js","type":"application/javascript","module-type":"widget","text":"/*\
title: $:/plugins/claude/bookmarks/drag.js
type: application/javascript
module-type: widget

Drag and drop for the bar: dragging bookmarks and folders into a new order,
dropping a tiddler or a link from anywhere else onto the bar to bookmark it,
and dragging a bookmark out to another window.

The widget renders no element of its own. It hangs its listeners on whatever
its children render — the link, or the folder's button — so the bar keeps
exactly the DOM it had before. That matters for more than tidiness:
TiddlyWiki positions a popup from its button's offset coordinates, so a
wrapper with position:relative here would displace every folder dropdown.

\*/
(function(){
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;
var core = require("$:/plugins/claude/bookmarks/core.js");

/* Our own transfer type, so a bar drag is told apart from any other drag */
var ENTRY_TYPE = "application/x-tiddlywiki-bookmarks-entry";
var ZONES = ["bm-drop-before","bm-drop-after","bm-drop-into"];

/* The bar drag in flight, if any: dataTransfer is unreadable until the drop */
var dragging = null;

function containsType(event,type){
	if($tw.utils.dragEventContainsType){ return $tw.utils.dragEventContainsType(event,type); }
	var types = event.dataTransfer && event.dataTransfer.types;
	return !!types && Array.prototype.indexOf.call(types,type) !== -1;
}

function containsFiles(event){
	return !!$tw.utils.dragEventContainsFiles && $tw.utils.dragEventContainsFiles(event);
}

var DragWidget = function(parseTreeNode,options){ this.initialise(parseTreeNode,options); };
DragWidget.prototype = new Widget();

DragWidget.prototype.render = function(parent,nextSibling){
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	if(this.zone === "end"){
		/* The run of empty bar past the last bookmark: a drop there appends */
		var node = this.document.createElement("span");
		node.className = "bm-drop-end";
		parent.insertBefore(node,nextSibling);
		this.domNodes.push(node);
		this.renderChildren(node,null);
		this.listen(node);
	} else {
		this.renderChildren(parent,nextSibling);
		this.listen(this.findFirstDomNode());
	}
};

DragWidget.prototype.execute = function(){
	this.entry = this.getAttribute("entry","");
	this.folder = this.getAttribute("folder","");
	this.axis = this.getAttribute("axis","x");
	this.zone = this.getAttribute("zone","item");
	this.isFolder = this.entry.substr(0,2) === "f:";
	this.makeChildWidgets();
};

DragWidget.prototype.listen = function(node){
	if(!node || !node.setAttribute){ return; }
	this.dropNode = node;
	/* A refresh can hand back the node we are already listening to */
	if(node.bmDragBound){ return; }
	node.bmDragBound = true;
	if(this.entry){ node.setAttribute("draggable","true"); }
	$tw.utils.addEventListeners(node,[
		{name: "dragstart", handlerObject: this, handlerMethod: "handleDragStartEvent"},
		{name: "dragend", handlerObject: this, handlerMethod: "handleDragEndEvent"},
		{name: "dragenter", handlerObject: this, handlerMethod: "handleDragOverEvent"},
		{name: "dragover", handlerObject: this, handlerMethod: "handleDragOverEvent"},
		{name: "dragleave", handlerObject: this, handlerMethod: "handleDragLeaveEvent"},
		{name: "drop", handlerObject: this, handlerMethod: "handleDropEvent"}
	]);
};

/* --- dragging one of our own ------------------------------------------- */

DragWidget.prototype.handleDragStartEvent = function(event){
	if(!this.entry || !event.dataTransfer){ return false; }
	dragging = {entry: this.entry, folder: this.folder};
	event.dataTransfer.effectAllowed = "all";
	event.dataTransfer.setData(ENTRY_TYPE,this.entry);
	/*
	Whatever the browser or the link widget already put on the drag is left
	alone, so a bookmark dragged into the wiki still imports its tiddler and
	one dragged to another window still carries its URL. A folder button has
	no payload of its own, so give it its name.
	*/
	if(this.isFolder){ event.dataTransfer.setData("text/plain",core.name(this.entry.substr(2))); }
	$tw.utils.addClass(this.dropNode,"bm-dragging");
	event.stopPropagation();
	return false;
};

DragWidget.prototype.handleDragEndEvent = function(event){
	dragging = null;
	if(this.dropNode){ $tw.utils.removeClass(this.dropNode,"bm-dragging"); }
	this.clearHighlight();
	return false;
};

/* --- working out where a drop lands ------------------------------------ */

/*
Which part of this entry the pointer is over: a bookmark splits in half, and
a folder keeps its middle for dropping things inside it, the way a browser's
bar does. The empty run at the end of the bar is only ever an append.
*/
DragWidget.prototype.dropZone = function(event){
	if(!this.entry){ return "before"; }
	var rect = this.dropNode.getBoundingClientRect();
	var along = this.axis === "y" ?
		(event.clientY - rect.top) / (rect.height || 1) :
		(event.clientX - rect.left) / (rect.width || 1);
	if(this.isFolder){
		if(along < 0.25){ return "before"; }
		return along > 0.75 ? "after" : "into";
	}
	return along < 0.5 ? "before" : "after";
};

/* The folder a drop puts things in, and the entry it should land in front of */
DragWidget.prototype.dropTarget = function(zone){
	if(!this.entry){ return {folder: this.folder, before: ""}; }
	if(zone === "into"){ return {folder: this.entry.substr(2), before: ""}; }
	if(zone === "before"){ return {folder: this.folder, before: this.entry}; }
	var list = core.entries(this.wiki,this.folder), next = "";
	for(var i = 0; i < list.length; i++){
		if(core.encode(list[i]) === this.entry){
			next = list[i + 1] ? core.encode(list[i + 1]) : "";
			break;
		}
	}
	return {folder: this.folder, before: next};
};

/* Spots core.place would refuse anyway, so the bar should not offer them */
DragWidget.prototype.refuses = function(zone){
	if(!dragging || !this.entry || zone !== "into"){ return false; }
	if(dragging.entry === this.entry){ return true; }
	if(dragging.entry.substr(0,2) !== "f:"){ return false; }
	var path = dragging.entry.substr(2), here = this.entry.substr(2);
	return here === path || here.substr(0,path.length + 1) === path + "/";
};

/* --- highlighting ------------------------------------------------------ */

DragWidget.prototype.highlight = function(zone){
	if(!this.dropNode){ return; }
	var wanted = "bm-drop-" + zone;
	for(var i = 0; i < ZONES.length; i++){
		if(ZONES[i] !== wanted){ $tw.utils.removeClass(this.dropNode,ZONES[i]); }
	}
	$tw.utils.addClass(this.dropNode,wanted);
};

DragWidget.prototype.clearHighlight = function(){
	if(!this.dropNode){ return; }
	for(var i = 0; i < ZONES.length; i++){ $tw.utils.removeClass(this.dropNode,ZONES[i]); }
};

/* --- taking a drop ----------------------------------------------------- */

DragWidget.prototype.handleDragOverEvent = function(event){
	if(["TEXTAREA","INPUT"].indexOf(event.target.tagName) !== -1){ return false; }
	if(containsFiles(event)){ return false; }
	var zone = this.dropZone(event);
	if(this.refuses(zone)){
		this.clearHighlight();
		event.dataTransfer.dropEffect = "none";
		return false;
	}
	/* Taking the default is how a drop target says it will accept the drop */
	event.preventDefault();
	event.stopPropagation();
	event.dataTransfer.dropEffect = dragging ? "move" : "copy";
	this.highlight(zone);
	return false;
};

DragWidget.prototype.handleDragLeaveEvent = function(event){
	var into = event.relatedTarget;
	if(into && this.dropNode && this.dropNode.contains(into)){ return false; }
	this.clearHighlight();
	return false;
};

DragWidget.prototype.handleDropEvent = function(event){
	var self = this;
	this.clearHighlight();
	if(containsFiles(event)){ return false; }
	var zone = this.dropZone(event);
	if(this.refuses(zone)){ return false; }
	var spot = this.dropTarget(zone);
	var entry = dragging ? dragging.entry :
		(containsType(event,ENTRY_TYPE) ? event.dataTransfer.getData(ENTRY_TYPE) : "");
	if(entry){
		core.place(this.wiki,entry,spot.folder,spot.before);
	} else {
		$tw.utils.importDataTransfer(event.dataTransfer,null,function(fieldsArray){
			fieldsArray.forEach(function(fields){ self.bookmarkDrop(fields,spot); });
		});
	}
	event.preventDefault();
	event.stopPropagation();
	return false;
};

/* Something from outside the bar: bookmark it where it was dropped */
DragWidget.prototype.bookmarkDrop = function(fields,spot){
	var title = String(fields.title || "").trim();
	var text = String(fields.text || "").trim();
	if(title){
		core.insert(this.wiki,{target: title},spot.folder,spot.before);
	} else if(core.normaliseUrl(text)){
		/* Only a real link is worth a bookmark; dropped prose is not */
		core.insert(this.wiki,{url: text},spot.folder,spot.before);
	}
};

DragWidget.prototype.refresh = function(changedTiddlers){
	var changedAttributes = this.computeAttributes();
	if(changedAttributes.entry || changedAttributes.folder ||
		changedAttributes.axis || changedAttributes.zone){
		this.refreshSelf();
		return true;
	}
	var refreshed = this.refreshChildren(changedTiddlers);
	/* A child that re-rendered has handed us a new node to listen to */
	if(refreshed && this.zone !== "end"){ this.listen(this.findFirstDomNode()); }
	return refreshed;
};

exports["bookmark-drag"] = DragWidget;

})();
